/* one association per supported type; no default = unsupported types fail the build */
#define ORDER_CMP(a, b)                                   \
    _Generic((a),                                         \
        int:          cmp_int,                            \
        double:       cmp_double,                         \
        char *:       cmp_cstr,                           \
        const char *: cmp_cstr)((a), (b))

/* property constant and operation shipped together, named by convention: */
typedef struct { size_t size; double (*to_double)(const void *); } num_traits;
static const num_traits int_traits = { sizeof(int), to_double_int };

/* the trait is the naming convention, not a language feature */
static inline size_t traits_len_int(const int *p, size_t n);
static inline size_t traits_len_cstr(const char *s);
static inline double traits_to_double_double(double v) { return v; }

/* caller picks the family explicitly (or a macro does): */
#define ARR_LEN(a) (sizeof(a) / sizeof((a)[0]))
#define CSTR_LEN(s) traits_len_cstr(s)

